"""Validate and render only saved aggregate sleeve results, never run a strategy."""
from pathlib import Path
import csv,hashlib,json,math
ROOT=Path(__file__).resolve().parents[1];RAW=ROOT/'.local/qc504-ablation-v1';OUT=ROOT/'.local/performance/qc504-ablation-v1'
CASES=('ensemble','t10','t11','s2','s3')
NAMES=dict(ensemble='Four-sleeve ensemble',t10='T10 · RSI cascade',t11='T11 · trend/bear rotation',s2='S2 · TQQQ trend gate',s3='S3 · trend vote/rebound')

def validate(rows,case):
    if not rows or any(r.get('study')!='qc504-ablation-v1' or r.get('case')!=case for r in rows):raise ValueError('Wrong study/case')
    full=[r for r in rows if r.get('kind')=='overall'];annual=sorted([r for r in rows if r.get('kind')=='annual'],key=lambda r:r['year'])
    if len(full)!=1 or [r['year'] for r in annual]!=[str(y) for y in range(2020,2026)]:raise ValueError('Incomplete summaries')
    f=full[0];nav=10000.;mom=squares=0.;n=uw=0
    for r in annual:
        nav*=1+r['ret'];mom+=r['return_sum'];squares+=r['return_square_sum'];n+=r['n'];uw+=r['global_uw']
        if not math.isclose(nav,r['end'],abs_tol=.1,rel_tol=1e-8):raise ValueError('Annual NAV mismatch')
        if r['annual_calmar'] is not None and not math.isclose(r['ret']/abs(r['dd']),r['annual_calmar'],abs_tol=1e-6):raise ValueError('Annual Calmar mismatch')
    if not math.isclose(nav,f['end'],abs_tol=.1,rel_tol=1e-8) or n!=f['n'] or uw!=f['uw']:raise ValueError('Totals mismatch')
    sd=math.sqrt(max(0,(squares-mom*mom/n)/(n-1)))
    if sd>1e-15 and not math.isclose(mom/n/sd*math.sqrt(252),f['sharpe'],abs_tol=1e-5):raise ValueError('Sharpe mismatch')
    if f['calmar'] is not None and not math.isclose(f['cagr']/abs(f['dd']),f['calmar'],abs_tol=1e-8):raise ValueError('Calmar mismatch')
    a=next(r for r in rows if r['kind']=='assets')
    f['pnl_residual_usd']=a['residual_usd']
    f['status']='conditional: rejected orders' if f['rejects'] else 'complete: no rejected orders'
    return f,annual

def build():
    ledger=json.loads((RAW/'attempts.json').read_text());plan=json.loads((ROOT/'research/plans/qc504-ablation-v1.json').read_text())
    runs=[];annual=[];missing=[]
    for case in CASES:
        p=RAW/f'{case}-summary-cells.json'
        if not p.exists():missing.append(case);continue
        rows=[json.loads(x) if isinstance(x,str) else x for x in json.loads(p.read_text())]
        f,ys=validate(rows,case);runs.append(f);annual+=ys
    if len({r['calendar_hash'] for r in runs})>1:raise ValueError('Mismatched session calendars')
    receipt=dict(study_id=plan['study_id'],status='complete' if not missing else 'partial',missing=missing,attempts=ledger['attempts'],git_sha=ledger['git_sha'],engine='LEAN2.5.0.0.18209 observed; verify per run',checks=['annual/full NAV compounding','annual/full Calmar','Sharpe moments','underwater totals','session-calendar hash alignment'],limits=['Hosted same-engine/data diagnostics, not independent replication','Full-budget standalone is not inside-ensemble profit attribution','Previously viewed development sample; no untouched OOS alpha','Funding and embedded leverage unqualified','Rejected-order paths conditional; no silent repair','No market impact/capacity validation'],source_hashes=plan['source_hashes'],selected_attempts={c:next((a for a in reversed(ledger['attempts']) if a['case']==c and a['status']=='completed-summary-captured'),None) for c in CASES},code_sha256={str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest() for p in [ROOT/'scripts/prepare_qc504_ablation.py',ROOT/'scripts/repair_qc504_ablation_reporting.py',ROOT/'scripts/parse_qc504_fragments.py',ROOT/'scripts/build_qc504_ablation.py',ROOT/'research/quantconnect/sector_metrics.py',ROOT/'research/plans/qc504-ablation-v1.json',ROOT/'research/plans/qc504-ablation-v1.frozen.json']},artifacts={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in list(RAW.glob('*summary-cells.json'))+list(RAW.glob('*terminal-fragments.json'))})
    data=dict(names=NAMES,runs=runs,annual=annual,evidence=receipt)
    OUT.mkdir(parents=True,exist_ok=True);(OUT/'comparison.json').write_text(json.dumps(data,indent=2)+'\n')
    with (OUT/'annual.csv').open('w') as fp:
        w=csv.DictWriter(fp,fieldnames=['case','year','ret','dd','sharpe','annual_calmar','global_uw','uw','n','longest_uw','end'],extrasaction='ignore');w.writeheader();w.writerows(annual)
    (OUT/'index.html').write_text(PAGE.replace('PAYLOAD',json.dumps(data).replace('</','<\\/')))
    (ROOT/'docs/tasks/evidence/2026-10-26-qc504-sleeve-ablation.json').write_text(json.dumps(receipt,indent=2)+'\n')
    (OUT/'manifest.json').write_text(json.dumps({p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in OUT.iterdir() if p.is_file() and p.name!='manifest.json'},indent=2)+'\n')
    print(json.dumps(dict(runs=runs,annual_rows=len(annual),missing=missing),indent=2))

PAGE='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>504 · sleeve ablation</title><style>body{font:15px system-ui;background:#f4f6f8;color:#203444;margin:0}main{max-width:1350px;margin:auto;padding:28px}p{line-height:1.6}h1{font-size:30px}.warn{background:#fff0d3;border-left:4px solid #a67115;padding:15px}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;background:white;font-variant-numeric:tabular-nums}td,th{padding:10px;text-align:right;border-bottom:1px solid #d8e1e7;white-space:nowrap}td:first-child,th:first-child{text-align:left}th{background:#e4ecf2}select{padding:8px;font:inherit}.small{font-size:12px;color:#526a7b}a{color:#135c8b}.flow{padding:16px;background:#e4ecf2;font-weight:600}.bad{color:#a03922}</style><main><p class="small">26 October 2026 · Frozen full-budget ablation · Five cases, maximum seven attempts (reporting amendment)</p><h1>Do four sleeves improve the tradeoff?</h1><p>2020–2025 · $10,000 each · 25bp slippage per fill · original IB margin/fee defaults · unchanged signal and MOO order policy. Standalone sleeves receive the full budget; ensemble retains four quarter budgets.</p><p class="warn">Development diagnostics on QuantConnect data/engine. Financing, embedded leverage, independent accounting and capacity remain unqualified. Rejected-order cases are conditional. Equal allocation budgets do not mean equal risk.</p><div class="flow">Frozen copied source → ensemble + four standalone sleeves → matched metrics → tradeoffs, not promotion</div><h2>Overall comparison</h2><label>Sort by <select id="rank"><option value="calmar">Calmar</option><option value="sharpe">Sharpe</option><option value="cagr">CAGR</option><option value="dd">Smaller drawdown</option><option value="longest_uw">Shorter underwater</option></select></label><p id="status"></p><div class="scroll"><table id="full"></table></div><h2>Time underwater</h2><div class="scroll"><table id="temporal"></table></div><h2>Year-by-year comparison</h2><label>Metric <select id="metric"><option value="ret">Annual return</option><option value="dd">Annual reset max drawdown</option><option value="sharpe">Sharpe</option><option value="annual_calmar">Annual Calmar</option><option value="longest_uw">Annual longest underwater sessions</option><option value="global_uw">Carried-peak underwater fraction</option></select></label><div class="scroll"><table id="years"></table></div><h2>Execution and accounting diagnostics</h2><div class="scroll"><table id="audit"></table></div><h2>How to interpret this</h2><ul><li>Standalone allocation uses full capital, not a 25% sleeve plus 75% cash. This is not realized inside-ensemble attribution.</li><li>Full Calmar = calendar CAGR / maximum drawdown depth. Annual Calmar = annual return / annual reset drawdown.</li><li>Sharpe = sample daily account-return mean / standard deviation × sqrt252, risk-free rate zero.</li><li>Underwater fraction carries peaks across years. Annual longest underwater resets its peak at the year boundary; full-period longest runs can cross boundaries. Calendar duration measures peak to last underwater mark, excluding recovery day.</li><li>All inspected history is development evidence. Native-book P&L residual is not an independent reconstruction of cash/fills/dividends.</li></ul><p><a href="annual.csv">Annual CSV</a> · <a href="comparison.json">Metrics and evidence</a> · <a href="https://www.quantconnect.com/project/38484741">Hosted research project</a></p></main><script>const d=PAYLOAD,cs=['ensemble','t10','t11','s2','s3'],pct=x=>x==null?'—':(x*100).toFixed(2)+'%',num=x=>x==null?'—':x.toFixed(2);document.getElementById('status').textContent=d.evidence.missing.length?'Missing: '+d.evidence.missing.join(', '):'Five complete summaries · all four standalone sleeves have rejected orders and are conditional; ensemble has zero. Sorting is descriptive.';function full(){let k=document.getElementById('rank').value;let rows=[...d.runs].sort((a,b)=>k==='longest_uw'?a[k]-b[k]:b[k]-a[k]);document.getElementById('full').innerHTML='<tr><th>Case</th><th>CAGR</th><th>Max DD</th><th>Sharpe</th><th>Calmar</th><th>Longest UW sessions</th><th>Rejected orders</th></tr>'+rows.map(r=>`<tr><td>${d.names[r.case]}</td><td>${pct(r.cagr)}</td><td>${pct(r.dd)}</td><td>${num(r.sharpe)}</td><td>${num(r.calmar)}</td><td>${r.longest_uw}</td><td class="${r.rejects?'bad':''}">${r.rejects}</td></tr>`).join('')}function years(){let k=document.getElementById('metric').value;document.getElementById('years').innerHTML='<tr><th>Year</th>'+cs.map(c=>'<th>'+d.names[c]+'</th>').join('')+'</tr>'+[2020,2021,2022,2023,2024,2025].map(y=>'<tr><td>'+y+'</td>'+cs.map(c=>{let r=d.annual.find(r=>r.case===c&&r.year===String(y));let v=r?.[k];if(k==='global_uw')v=r?v/r.n:null;return '<td>'+(['ret','dd','global_uw'].includes(k)?pct(v):k==='longest_uw'?(v??'—'):num(v))+'</td>'}).join('')+'</tr>').join('')}document.getElementById('temporal').innerHTML='<tr><th>Case</th><th>Underwater fraction</th><th>Longest sessions</th><th>Calendar days</th><th>Unrecovered at end</th></tr>'+d.runs.map(r=>`<tr><td>${d.names[r.case]}</td><td>${pct(r.uw_fraction)}</td><td>${r.longest_uw}</td><td>${r.longest_uw_days}</td><td>${r.censored?'Yes':'No'}</td></tr>`).join('');document.getElementById('audit').innerHTML='<tr><th>Case</th><th>Ending NAV</th><th>Fees USD</th><th>Rejected</th><th>Fill events</th><th>Non-MOO fills</th><th>Max fund gross</th><th>Minimum cash USD</th><th>Native P&L residual USD</th><th>Sessions</th></tr>'+d.runs.map(r=>`<tr><td>${d.names[r.case]}</td><td>${num(r.end)}</td><td>${num(r.fees)}</td><td>${r.rejects}</td><td>${r.fills}</td><td>${r.other_fills}</td><td>${num(r.max_gross)}×</td><td>${num(r.min_cash)}</td><td>${r.pnl_residual_usd.toFixed(4)}</td><td>${r.n}</td></tr>`).join('');document.getElementById('rank').onchange=full;document.getElementById('metric').onchange=years;full();years();</script></html>'''
if __name__=='__main__':build()
